package com.bank.notify;

import java.util.*;
import java.util.logging.*;

public class NotificationDemo {
    private static final Logger log = Logger.getLogger(NotificationDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // SIMPLE start: one channel. No plugin framework, no God class.
        NotificationService service = new NotificationService();
        service.register(new SmsChannel());

        log.info("=== Today: single SMS channel (simplest correct design) ===");
        service.notifyCustomer("Rajesh", "Rs.50000 debited from SAV2001");

        // "How would you extend this?" → OCP: ADD a new class, DO NOT modify existing.
        log.info("=== Extension via Open/Closed: add EmailChannel (new class) ===");
        service.register(new EmailChannel()); // existing SmsChannel + service untouched
        service.notifyCustomer("Priya", "Rs.75000 credited to CUR3001");
    }
}

// ─── channel/NotificationChannel.java — the ONE seam along a likely axis of change ───
interface NotificationChannel {
    void send(String customer, String message);
    String name();
}

// ─── channel/SmsChannel.java — initial implementation ───
class SmsChannel implements NotificationChannel {
    private static final Logger log = Logger.getLogger(SmsChannel.class.getName());
    public void send(String customer, String message) {
        log.info(() -> "[SMS] to " + customer + ": " + message);
    }
    public String name() { return "SMS"; }
}

// ─── channel/EmailChannel.java — ADDED LATER. New class, zero edits to existing code. ───
class EmailChannel implements NotificationChannel {
    private static final Logger log = Logger.getLogger(EmailChannel.class.getName());
    public void send(String customer, String message) {
        log.info(() -> "[EMAIL] to " + customer + ": " + message);
    }
    public String name() { return "EMAIL"; }
}

// ─── service/NotificationService.java — THIN and SIMPLE, closed for modification ───
class NotificationService {
    private static final Logger log = Logger.getLogger(NotificationService.class.getName());
    private final List<NotificationChannel> channels = new ArrayList<>();

    void register(NotificationChannel channel) {
        channels.add(channel);
        log.fine(() -> "Registered channel " + channel.name());
    }

    // This method NEVER changes when a new channel is added (Open/Closed).
    void notifyCustomer(String customer, String message) {
        for (NotificationChannel channel : channels) {
            channel.send(customer, message);
        }
    }
}

// ─── util/BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
